{"command": "cat > /app/task_file/output/ko-debug.js << 'EOF'
/**
 * KnockoutJS Template Binding Error Debugger
 * 
 * A utility that intercepts and enhances KnockoutJS binding errors
 * with actionable suggestions for fixing typos in property names.
 */

/**
 * Computes the Levenshtein distance between two strings.
 * This is the minimum number of single-character edits
 * (insertions, deletions, or substitutions) required to change
 * one string into the other.
 *
 * @param {string} a - The first string
 * @param {string} b - The second string
 * @returns {number} The Levenshtein distance
 */
function levenshteinDistance(a, b) {
  const m = a.length;
  const n = b.length;

  // Create a (m+1) x (n+1) matrix
  const dp = Array.from({ length: m + 1 }, () => Array(n + 1).fill(0));

  // Base cases
  for (let i = 0; i <= m; i++) {
    dp[i][0] = i;
  }
  for (let j = 0; j <= n; j++) {
    dp[0][j] = j;
  }

  // Fill in the rest of the matrix
  for (let i = 1; i <= m; i++) {
    for (let j = 1; j <= n; j++) {
      const cost = a[i - 1] === b[j - 1] ? 0 : 1;
      dp[i][j] = Math.min(
        dp[i - 1][j] + 1,       // deletion
        dp[i][j - 1] + 1,       // insertion
        dp[i - 1][j - 1] + cost // substitution
      );
    }
  }

  return dp[m][n];
}

/**
 * Finds the closest matching property name using Levenshtein distance.
 * Only returns a suggestion if the distance is 3 or less.
 * If multiple properties tie, returns the one that comes first alphabetically.
 *
 * @param {string} missingProperty - The property name that was not found
 * @param {string[]} availableProperties - Sorted list of available property names
 * @returns {string|null} The closest matching property name, or null
 */
function findClosestMatch(missingProperty, availableProperties) {
  let bestDistance = Infinity;
  let bestMatch = null;

  for (const prop of availableProperties) {
    const dist = levenshteinDistance(missingProperty, prop);
    if (dist <= 3) {
      if (dist < bestDistance || (dist === bestDistance && prop < bestMatch)) {
        bestDistance = dist;
        bestMatch = prop;
      }
    }
  }

  return bestMatch;
}

/**
 * Creates a debug helper for diagnosing KnockoutJS binding errors.
 *
 * @param {Object} viewModel - A KnockoutJS-style ViewModel object
 * @returns {Object} A debug helper with the diagnoseMissingProperty method
 */
function createDebugHelper(viewModel) {
  // Get sorted list of available properties on the ViewModel
  const availableProperties = Object.keys(viewModel).sort();

  /**
   * Diagnoses a missing property binding error.
   *
   * @param {string} propertyName - The name of the property that failed to bind
   * @returns {Object} An object with error details, available properties, and suggestions
   */
  function diagnoseMissingProperty(propertyName) {
    const suggestion = findClosestMatch(propertyName, availableProperties);

    return {
      error: true,
      missingProperty: propertyName,
      availableProperties: availableProperties,
      suggestion: suggestion
    };
  }

  return {
    diagnoseMissingProperty: diagnoseMissingProperty
  };
}

module.exports = {
  createDebugHelper: createDebugHelper,
  levenshteinDistance: levenshteinDistance
};
EOF"}

{"command": "cat > /app/task_file/output/test-ko-debug.js << 'EOF'
/**
 * Test script for the KnockoutJS Template Binding Error Debugger
 */

const { createDebugHelper } = require('./ko-debug');

// Define a sample ViewModel with the required properties
const sampleViewModel = {
  items: [],
  selectedItem: null,
  filterText: '',
  isLoading: false,
  totalCount: 0
};

// Create the debug helper
const helper = createDebugHelper(sampleViewModel);

// Test runner helper
function runTest(testNumber, description, actual, expected) {
  const passed = JSON.stringify(actual) === JSON.stringify(expected);
  console.log(`Test ${testNumber}: ${description} - ${passed ? 'PASS' : 'FAIL'}`);
  if (!passed) {
    console.log(`  Expected: ${JSON.stringify(expected)}`);
    console.log(`  Actual:   ${JSON.stringify(actual)}`);
  }
  return passed;
}

let allPassed = true;

// Test 1: Diagnose missing property "item" (should suggest "items")
const test1Result = helper.diagnoseMissingProperty('item');
const test1 = runTest(1,
  'Missing "item" should suggest "items"',
  test1Result,
  {
    error: true,
    missingProperty: 'item',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: 'items'
  }
);
allPassed = allPassed && test1;

// Test 2: Diagnose missing property "selctedItem" (should suggest "selectedItem")
const test2Result = helper.diagnoseMissingProperty('selctedItem');
const test2 = runTest(2,
  'Missing "selctedItem" should suggest "selectedItem"',
  test2Result,
  {
    error: true,
    missingProperty: 'selctedItem',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: 'selectedItem'
  }
);
allPassed = allPassed && test2;

// Test 3: Diagnose missing property "completelyWrong" (should have null suggestion)
const test3Result = helper.diagnoseMissingProperty('completelyWrong');
const test3 = runTest(3,
  'Missing "completelyWrong" should have null suggestion',
  test3Result,
  {
    error: true,
    missingProperty: 'completelyWrong',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: null
  }
);
allPassed = allPassed && test3;

// Test 4: Diagnose missing property "isLoad" (should suggest "isLoading")
const test4Result = helper.diagnoseMissingProperty('isLoad');
const test4 = runTest(4,
  'Missing "isLoad" should suggest "isLoading"',
  test4Result,
  {
    error: true,
    missingProperty: 'isLoad',
    availableProperties: ['filterText', 'isLoading', 'items', 'selectedItem', 'totalCount'],
    suggestion: 'isLoading'
  }
);
allPassed = allPassed && test4;

// Summary
console.log('');
console.log(`=================================`);
console.log(allPassed ? 'All 4 tests PASSED!' : 'Some tests FAILED!');
console.log(`=================================`);

// Exit with appropriate code
process.exit(allPassed ? 0 : 1);
EOF"}

